"""Content, reference and runtime wiring checks independent of recovery data."""
import importlib
import itertools
import math
import ast
from collections import Counter
from .ontology import Knowledge, read


REQUIRED = {
    "hands": "high_guard philly_shell peekaboo cross_arm long_guard helmet shield52 hands_down kronk dutch_guard".split(),
    "defense": "slip_roll parry_catch block_absorb outfight shoulder_roll smother check_frame sprawl_pummel".split(),
    "stance": "upright bladed crouch balanced planted switch shuffle".split(),
    "tie": "thai_plum greco folk_ride freestyle judo_sambo bjj wall_boxing anti_grappling".split(),
    "target": "head_hunter body_puncher leg_chopper liver_ribs knee_clincher mixer".split(),
    "kicking": "none muay_thai dutch karate sanda wrestler_teep".split(),
    "mentality": "outboxer swarmer counter slugger boxer_puncher switch_hitter defensive pressure spoiler slickster showman technician".split()}
MATRICES = {"mentality_mentality": ("mentality", "mentality"), "stance_stance": ("stance", "stance"),
            "hands_target": ("hands", "target"), "defense_target": ("defense", "target"),
            "defense_kicking": ("defense", "kicking"), "stance_kicking": ("stance", "kicking"),
            "tie_tie": ("tie", "tie"), "tie_stance": ("tie", "stance")}
TYPES = {"BEATS", "LOSES_TO", "COMPATIBLE_WITH", "INCOMPATIBLE_WITH", "EXPOSES", "EXPLOITED_BY", "REQUIRES", "ENABLES", "COUNTERS", "TRANSITIONS_TO", "ADAPTS_TO", "CAUSES"}


def audit(root=None):
    errors, warnings = [], []
    try:
        k = Knowledge(root) if root else Knowledge()
    except (OSError, ValueError, KeyError) as exc:
        return {"status": "FAIL", "errors": ["knowledge load: " + str(exc)], "warnings": [], "counts": {}}

    def need(condition, message):
        if not condition:
            errors.append(message)

    def fields(record, required, context):
        for field in required.split():
            need(field in record and record[field] not in [None, "", [], {}], context + " missing " + field)

    def provenance(prov, context):
        need(prov.get("classification") in ["CANON", "VERIFIED"], context + " classification")
        for claim in prov.get("basis_claims", []):
            need(claim in k.claims, context + " unknown claim " + claim)
        if prov.get("classification") == "VERIFIED":
            need(bool(prov.get("source_ids")), context + " unsupported verified label")
            for src in prov.get("source_ids", []):
                need(src in k.sources, context + " unknown source " + src)

    expected = {d + "." + i for d, ids in REQUIRED.items() for i in ids}
    need(set(k.options) == expected, "mandatory ontology ID coverage")
    need(set(k.index["dimensions"]) == set(REQUIRED), "dimension index coverage")
    for dim, ids in REQUIRED.items():
        need(set(k.index["dimensions"].get(dim, [])) == {dim + "." + i for i in ids}, "dimension index " + dim)
    out, incoming = Counter(), Counter()
    for r in k.relationships.values():
        if r["type"] == "COUNTERS":
            out[r["source_id"]] += 1
            incoming[r["destination_id"]] += 1
    for ident, option in k.options.items():
        fields(option, "id name dimension description reference_anchor boxing_form mma_adaptation mechanical_advantages derived_liabilities counter_relationships compatible_options incompatible_options ratings preferred_ranges tactical_conditions technique_refs exploitable_debt_ids provenance", ident)
        provenance(option.get("provenance", {}), ident)
        need(all(isinstance(v, int) and 1 <= v <= 5 for v in option["ratings"].values()), ident + " ratings outside 1–5")
        for adaptation in ["boxing_form", "mma_adaptation"]:
            fields(option[adaptation], "description ratings covers", ident + " " + adaptation)
            need(all(1 <= v <= 5 for v in option[adaptation]["ratings"].values()), ident + " adaptation ratings")
        need(out[ident] >= 2 and incoming[ident] >= 1, ident + " lacks incoming/outgoing counters")
        for tid in option["technique_refs"]:
            need(tid in k.techniques, ident + " unknown technique " + tid)
        for did in option["exploitable_debt_ids"]:
            need(did in k.debts and k.debts[did]["option_id"] == ident, ident + " invalid debt " + did)
        for r in option["counter_relationships"]:
            need(r in k.relationships and k.relationships[r]["source_id"] == ident and k.relationships[r]["type"] == "COUNTERS", ident + " invalid counter pointer")
        for field in ["compatible_options", "incompatible_options"]:
            need(all(x in k.options for x in option[field]), ident + " invalid option relationship")
        if option["dimension"] == "stance":
            fields(option, "carryover", ident)
        if option["dimension"] == "mentality":
            fields(option, "strengths weaknesses natural_tempo stamina_drain_tendency on_screen_behavior", ident)
        if option["dimension"] == "target":
            fields(option, "exploits shut_down_by", ident)
    for did, debt in k.debts.items():
        fields(debt, "id option_id opening mechanical_tradeoff exploiters technique_ids required_range ruleset classification", did)
        need(debt["option_id"] in k.options, did + " missing source")
        need(all(x in k.options for x in debt["exploiters"]), did + " missing exploiter")
        need(all(x in k.techniques for x in debt["technique_ids"]), did + " missing exploit technique")
        for x in debt["exploiters"]:
            need(debt["opening"] in k.options[x]["tactical_conditions"]["answers"], did + " unsupported exploit")
    caps = {"cap." + c for t in k.techniques.values() for c in t["required_capabilities"]}
    known = set(k.options) | set(k.debts) | set(k.techniques) | caps
    seen = set()
    for r in k.relationships.values():
        fields(r, "id source_id destination_id type mechanism preconditions ruleset classification", r["id"])
        need(r["type"] in TYPES, "unknown relationship type")
        need(r["source_id"] in known and r["destination_id"] in known, "dangling graph reference " + r["id"])
        key = (r["source_id"], r["destination_id"], r["type"])
        need(key not in seen, "duplicate graph relationship")
        seen.add(key)
        need(r["classification"] == "CANON", "tactical relationship may not claim empirical verification")
        if r["type"] == "COUNTERS" and r["source_id"] in k.options and r["destination_id"] in k.options:
            a, b = k.options[r["source_id"]], k.options[r["destination_id"]]
            need(bool(set(a["tactical_conditions"]["answers"]) & set(b["tactical_conditions"]["exposes"])), "unsupported counter mechanism " + r["id"])
            need((r["destination_id"], r["source_id"], "LOSES_TO") in {(x["source_id"], x["destination_id"], x["type"]) for x in k.relationships.values()}, "missing reciprocal counter")
    need({r["type"] for r in k.relationships.values()} == TYPES, "relationship type coverage")
    for a, b in [("outboxer", "slugger"), ("slugger", "swarmer"), ("swarmer", "outboxer")]:
        need(("mentality." + a, "mentality." + b, "BEATS") in seen, "missing conditional triangle")
    need(set(k.matrices) == set(MATRICES), "required matrix coverage")
    cell_count = 0
    for mid, (rd, cd) in MATRICES.items():
        if mid not in k.matrices:
            continue
        matrix = k.matrices[mid]
        keys = [(c["row_id"], c["column_id"]) for c in matrix["cells"]]
        expected_pairs = set(itertools.product([rd + "." + i for i in REQUIRED[rd]], [cd + "." + i for i in REQUIRED[cd]]))
        need(len(keys) == len(set(keys)) and set(keys) == expected_pairs, mid + " duplicate/missing cells")
        cell_count += len(keys)
        for cell in matrix["cells"]:
            fields(cell, "id row_id column_id mechanism preconditions defended_openings how classification numeric_basis", cell["id"])
            edge = cell["edge"]
            need(isinstance(edge, (float, int)) and math.isfinite(edge) and -1 <= edge <= 1, cell["id"] + " invalid edge")
            need(cell["favored_side"] == ("row" if edge > 0 else "column" if edge < 0 else "neutral"), cell["id"] + " inverted favored side")
            need(all(x in k.debts for x in cell["exploited_debt_ids"]), cell["id"] + " unknown cell debt")
            if rd == cd:
                reverse = k.cells[mid].get((cell["column_id"], cell["row_id"]))
                need(reverse is not None and edge == -reverse["edge"], cell["id"] + " reciprocity")
                if cell["row_id"] == cell["column_id"]:
                    need(edge == 0, "self matchup nonzero")
        if rd == cd:
            for row in REQUIRED[rd]:
                values = [c["edge"] for c in matrix["cells"] if c["row_id"] == rd + "." + row and c["row_id"] != c["column_id"]]
                need(not values or not all(v > 0 for v in values), "universally dominant matrix option " + row)
                if values and all(v >= 0 for v in values) and any(v > 0 for v in values):
                    warnings.append({"option": rd + "." + row, "finding": "Weakly non-losing base row; ties and cross-dimensional liabilities remain. Not universal dominance.", "incoming_counters": incoming[rd + "." + row]})
    need(cell_count == 511, "511-cell requirement")
    weights = k.model["weights"]
    need(set(weights) == set(MATRICES) and math.isclose(sum(weights.values()), 1), "matrix weights not normalized")
    need(all(v > 0 for v in weights.values()) and weights["mentality_mentality"] > weights["stance_stance"] >= weights["tie_stance"] and weights["mentality_mentality"] > weights["tie_tie"] >= weights["tie_stance"], "dimension priority")
    for tid, t in k.techniques.items():
        fields(t, "id name description combat_schools ruleset_legality starting_stance required_range required_body_configuration setup_actions execution_phases attacking_limb target_region direction_trajectory contact_conditions defensive_counters recovery_requirements balance_support expected_state_changes potential_failure_conditions visual_readability provenance kind required_capabilities", tid)
        need(all(x in k.techniques for x in t["defensive_counters"] + t["follow_up_opportunities"]), tid + " invalid follow-up/counter")
        need(all(x == "observe" or x == "grip" or x in k.techniques for x in t["setup_actions"]), tid + " invalid setup")
        provenance(t["provenance"], tid)
    combos = read(k.root / "data/combinations.json")["combinations"]
    for combo in combos:
        need(combo["from"] in k.techniques and combo["to"] in k.techniques and combo["success"] == "possible, never guaranteed", "invalid technique combination")
    for claim in k.claims.values():
        fields(claim, "id classification source_ids claim limits", claim["id"])
        need(all(src in k.sources for src in claim["source_ids"]), "unsupported verified source label " + claim["id"])
    for source in k.sources.values():
        fields(source, "id title publisher url access_date applicable_claim evidence_limitations access_method", source["id"])
        need(source["url"].startswith("https://"), "source URL")
    card_ids = set()
    for path in sorted((k.root / "cards").glob("*.json")):
        try:
            card = k.card(path)
            need(card["fighter_id"] not in card_ids, "duplicate fighter ID")
            card_ids.add(card["fighter_id"])
        except Exception as exc:
            errors.append(path.name + ": " + str(exc))
    need(len(card_ids) >= 11 and {"maleek", "donnell", "macklin", "detroit", "philly"} <= card_ids, "mandatory fighter coverage")
    eventids = set()
    for mapping in k.pipeline["event_types"]:
        eventids.add(mapping["id"])
        for key in ["state_handler", "choreography_handler", "prompt_handler"]:
            module, symbol = mapping[key].rsplit(".", 1)
            try:
                module_path = k.root / (module.replace(".", "/") + ".py")
                declared = {n.name for n in ast.parse(module_path.read_text()).body if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))}
                need(symbol in declared, "missing handler declaration " + mapping[key])
                need(callable(getattr(importlib.import_module(module), symbol)), "unreachable " + mapping[key])
            except (ImportError, AttributeError, OSError, SyntaxError):
                errors.append("unreachable " + mapping[key])
        fields(mapping, "technique_kinds", "event mapping " + mapping["id"])
    from .fight_state import HANDLERS
    need(eventids == set(HANDLERS), "missing/unhandled event types")
    for doc in k.pipeline["required_docs"]:
        need((k.root / doc).is_file() and bool((k.root / doc).read_text().strip()), "missing documentation " + doc)
    return {"status": "PASS" if not errors else "FAIL", "errors": errors, "warnings": warnings,
            "counts": {"ontology_options": len(k.options), "matchup_cells": cell_count, "fighter_cards": len(card_ids),
                       "techniques": len(k.techniques), "relationships": len(k.relationships),
                       "counter_relationships": sum(r["type"] == "COUNTERS" for r in k.relationships.values()),
                       "debts": len(k.debts), "debt_exploit_relationships": sum(r["type"] == "EXPLOITED_BY" for r in k.relationships.values()),
                       "event_types": len(eventids), "sources": len(k.sources), "verified_claims": len(k.claims)},
            "knowledge_sha256": k.fingerprint(), "provenance": "Verified claims resolve to accessed sources. All matchup values and tactical interpretations are CANON; factual verification is not inferred from pointer validity."}

engine/capabilities.py.content:
KNOWN_CAPABILITIES = {
    "anti_grappling",
    "basic_movement",
    "bjj",
    "boxing",
    "cage_plum",
    "clinch",
    "inside_combinations",
    "judo",
    "karate",
    "kickboxing",
    "pressure_footwork",
    "sanda",
    "shield",
    "switch_step",
    "untrained_striking",
    "wall_boxing",
    "wrestling",
}

OPTION_REQUIRED_TECHS = {
    "hands.shield52": {"shield_frame"},
    "hands.dutch_guard": {"low_kick"},
    "defense.smother": {"pummel"},
    "defense.check_frame": {"check", "shield_frame"},
    "defense.sprawl_pummel": {"sprawl", "pummel"},
    "stance.switch": {"switch_step"},
    "mentality.switch_hitter": {"switch_step"},
    "target.leg_chopper": {"low_kick"},
    "target.knee_clincher": {"knee_body", "collar_tie"},
}

UNTRAINED_PUNCH_OPTIONS = {
    "hands.hands_down",
    "defense.block_absorb",
    "stance.planted",
    "target.head_hunter",
    "kicking.none",
    "mentality.slugger",
    "mentality.showman",
}


def training(card, activated=()):
    caps = set(card["baseline_capabilities"])
    caps.update(c for slot in card["synchronized_capabilities"] for c in slot["capabilities"])
    caps.update(a["grants_capability"] for a in card["conditional_abilities"] if a["id"] in activated)
    return caps


def slot_signature(slot):
    """Semantic identity of a synchronized bundle: unordered capability set plus optional ordered sequence."""
    caps = frozenset(slot.get("capabilities") or ())
    seq = tuple(slot.get("coordination_sequence") or ())
    return caps, seq


def admitted_slots(card, k=None):
    """Return distinct admitted synchronized capability bundles; duplicate semantic bundles earn no extra credit."""
    admitted = []
    seen = set()
    active_techs = set(card.get("active_techniques") or ())
    for slot in card.get("synchronized_capabilities") or ():
        caps = slot.get("capabilities") or []
        if not caps or len(caps) != len(set(caps)):
            continue
        if any(c not in KNOWN_CAPABILITIES for c in caps):
            continue
        seq = slot.get("coordination_sequence")
        if seq is not None:
            if not isinstance(seq, (list, tuple)) or len(seq) < 2:
                continue
            if any(t not in active_techs for t in seq):
                continue
        sig = slot_signature(slot)
        if sig in seen:
            continue
        seen.add(sig)
        admitted.append(slot)
    return admitted


def option_supported(k, card, opt_id):
    """Verify that a selected dimension option is backed by the card's trained capabilities and active techniques."""
    if opt_id is None:
        return True
    if opt_id not in k.options:
        return False
    opt = k.options[opt_id]
    dim = opt["dimension"]
    tr = training(card)
    active = {
        tid
        for tid in card.get("active_techniques", [])
        if tid in k.techniques and (set(k.techniques[tid]["required_capabilities"]) & tr)
    }
    trefs = opt["technique_refs"]
    if dim == "tie":
        tie_trefs = [tid for tid in trefs if tid != "body_hook"]
        return any(tid in active for tid in tie_trefs)
    if dim == "kicking":
        if opt_id == "kicking.none":
            return bool(active)
        kick_trefs = [tid for tid in trefs if k.techniques[tid]["kind"] == "kick"]
        return any(tid in active for tid in kick_trefs)
    if opt_id in OPTION_REQUIRED_TECHS:
        return bool(OPTION_REQUIRED_TECHS[opt_id] & active)
    if any(tid in active for tid in trefs):
        return True
    if opt_id in UNTRAINED_PUNCH_OPTIONS and "untrained_striking" in tr and "haymaker" in active:
        return True
    return False


def resolved_dimensions(k, card):
    """Resolve supported dimension options; unsupported labels downgrade to None."""
    return {
        dim: (opt_id if option_supported(k, card, opt_id) else None)
        for dim, opt_id in card["dimensions"].items()
    }


def available(k, card, ruleset, activated=()):
    tids = set(card["active_techniques"])
    tids.update(t for a in card["conditional_abilities"] if a["id"] in activated for t in a["techniques"])
    caps = training(card, activated)
    return {tid for tid in tids if ruleset in k.techniques[tid]["ruleset_legality"]
            and set(k.techniques[tid]["required_capabilities"]) & caps}


def reachable(k, attacker, victim, ruleset):
    """Return evidence for potential access, never a claim that the attack has landed.

    Standing adjacent range steps are basic movement. Ground access needs a trained
    entry; an unattached bottom submission alone cannot create ground access.
    """
    tids = available(k, attacker, ruleset)
    has_ground_entry = any(k.techniques[t]["kind"] == "takedown" for t in tids)
    dims = resolved_dimensions(k, victim)
    canonical_debts = [
        d for opt_id in dims.values() if opt_id for d in k.options[opt_id]["exploitable_debt_ids"]
    ]
    seams = list(dict.fromkeys([d for d in victim.get("exploitable_seams", []) if d in k.debts] + canonical_debts))
    reports = []
    for did in seams:
        debt = k.debts[did]
        usable = [t for t in debt["technique_ids"] if t in tids]
        in_rules = ruleset in debt["ruleset"]
        ground_ok = debt["required_range"] != "ground" or has_ground_entry
        ok = bool(usable) and in_rules and ground_ok
        reports.append({"debt_id": did, "victim_id": victim["fighter_id"], "attacker_id": attacker["fighter_id"],
                        "opening": debt["opening"], "reachable": ok, "technique_ids": usable,
                        "required_range": debt["required_range"],
                        "path": ["adjacent standing steps", "trained ground entry"] if debt["required_range"] == "ground" else ["adjacent standing steps"],
                        "mechanism": debt["mechanical_tradeoff"],
                        "reason": "Trained technique and a legal access path exist; opponent can still deny access." if ok else
                        "Illegal under ruleset." if not in_rules else "No ground entry." if not ground_ok else "Required technique is not active."})
    return reports


def null_seams(k, attacker, victim, ruleset):
    """A single penalty per missing dimension, regardless of number of attacks."""
    legal_dims = k.model["rulesets"][ruleset]["dimensions"]
    tids = available(k, attacker, ruleset)
    dims = resolved_dimensions(k, victim)
    result = []
    for dim, selected in dims.items():
        if selected is not None:
            continue
        candidates = []
        for tid in sorted(tids):
            t = k.techniques[tid]
            if dim == "tie" and t["kind"] in ["takedown", "grip"]:
                if t["required_body_configuration"]["grip"] is None:
                    candidates.append(tid)
            elif dim in ["hands", "defense"] and t["kind"] == "punch":
                candidates.append(tid)
            elif dim == "stance" and t["kind"] in ["kick", "takedown"]:
                candidates.append(tid)
        relevant = dim in legal_dims
        result.append({"victim_id": victim["fighter_id"], "attacker_id": attacker["fighter_id"],
                       "dimension": dim, "reachable": relevant and bool(candidates),
                       "technique_ids": candidates if relevant else [],
                       "required_range": k.techniques[candidates[0]]["required_range"][0] if candidates else None,
                       "reason": "Legal trained entry can reach an initially uncovered capability." if relevant and candidates else
                       "Dimension unavailable in this ruleset." if not relevant else "Opponent has no legal trained entry.",
                       "conditional_mitigations": [a["id"] for a in victim["conditional_abilities"]]})
    return result


def compatibility(k, card):
    dims = resolved_dimensions(k, card)
    selected = [k.options[i] for i in dims.values() if i]
    result = []
    for n, a in enumerate(selected):
        for b in selected[n + 1:]:
            shared = sorted(set(a["preferred_ranges"]) & set(b["preferred_ranges"]))
            result.append({"fighter_id": card["fighter_id"], "options": [a["id"], b["id"]],
                           "shared_ranges": shared, "status": "shared range" if shared else "transition required",
                           "effect": "Sequence the two trained expressions after recovery." if shared else
                           "Move through adjacent ranges; no simultaneous range bonus.", "additional_logit": 0})
    return result


def admit_ranked_result(record):
    """Consumer-boundary guard: reject conditional narrative outputs and uncalibrated predictions as empirical ranked outcomes."""
    if not isinstance(record, dict):
        raise ValueError("ranked result must be a structured record")
    if "events" in record or "selection" in record or "final_state" in record:
        raise ValueError("conditional fight plan / narrative choreography cannot be ingested as an empirical ranked result")
    if "probability_a" in record or "matrix_edges" in record:
        raise ValueError("uncalibrated matchup prediction cannot be ingested as an empirical ranked result")
    mode = record.get("mode") or record.get("origin")
    if mode in {"predictive", "director-controlled", "director", "narrative", "simulated"}:
        raise ValueError("narrative or director-selected outcomes are ineligible for empirical ranking")
    if record.get("origin") != "independent_adjudicated_match" or not record.get("result_id") or not record.get("ruleset"):
        raise ValueError("empirical ranking requires an independently adjudicated match record with result_id and ruleset")
    return True

engine/choreography.py.content:
def groups(events):
    """Keep a complete action, including its setup/contact/reaction, in one shot."""
    current = []
    for e in events:
        if e["type"] == "setup":
            if current:
                raise ValueError("overlapping choreographed actions")
            current = [e]
        elif current:
            current.append(e)
            if e["type"] == "recovery":
                yield current
                current = []
        else:
            yield [e]
    if current:
        raise ValueError("unfinished choreographed action")


def anatomical(limb, orientation):
    lead = "left" if orientation == "orthodox" else "right"
    rear = "right" if orientation == "orthodox" else "left"
    return limb.replace("lead", lead).replace("rear", rear)


def translate(k, events, style="realistic"):
    if style not in ["realistic", "anime"]:
        raise ValueError("unsupported style; no supernatural technique is defined")
    first, last = events[0], events[-1]
    execution = next((e for e in events if e["type"] in ["execution", "movement"]), None)
    contact = next((e for e in events if e["type"] == "contact"), None)
    tech = k.techniques[execution["technique_id"]] if execution else None
    actor = first["actor_id"]
    phases = []
    mapping = {"preparation": ["setup", "assessment", "adjustment", "activation"],
               "initiation": ["execution", "movement"], "execution": ["execution", "movement"],
               "contact": ["contact"], "reaction": ["reaction"], "recovery": ["recovery", "resolution", "aftermath"]}
    for phase, types in mapping.items():
        matching = [e for e in events if e["type"] in types]
        phases.append({"phase": phase, "event_ids": [e["id"] for e in matching],
                       "timing": [{"start": e["timestamp"], "end": e["timestamp"] + e["duration"]} for e in matching],
                       "instructions": [e["intent"] for e in matching] if matching else ["No " + phase + " action in this beat."]})
    return {"movement_id": "movement." + first["id"], "source_event_ids": [e["id"] for e in events],
            "start": first["timestamp"], "end": last["timestamp"] + last["duration"], "phases": phases,
            "actor_id": actor, "target_id": first["target_id"], "technique_id": tech["id"] if tech else None,
            "limb_action": anatomical(tech["attacking_limb"], execution["state_before"]["actors"][actor]["orientation"]) if tech else "Observe/adjust without an invented attack.",
            "motion_trajectory": tech["direction_trajectory"] if tech else first["intent"],
            "contact": {"event_id": contact["id"], "time": contact["timestamp"], "region": tech["target_region"],
                        "outcome": contact["parameters"]["outcome"], "initiator": actor, "recipient": first["target_id"]} if contact else None,
            "start_actors": first["state_before"]["actors"], "end_actors": last["state_after"]["actors"],
            "weight_support": [{"event_id": e["id"], "support": e["state_after"]["actors"][actor]["foot_support"],
                                "balance": e["state_after"]["actors"][actor]["balance"]} for e in events],
            "environment": "Cage or ring floor; no hand grasps the fence. No props are introduced.",
            "prop_interaction": [],
            "visible_consequences": last["state_after"]["actors"][first["target_id"]]["injuries"],
            "motion_class": "realistic semantic staging" if style == "realistic" else "stylized anime exaggeration",
            "physical_claim": "No skeletal solver; not physically verified. Impossible supernatural action requires an explicitly authored technique, absent in this release."}


def choreograph(k, plan, style="realistic"):
    return {"version": plan["version"], "geometry": plan["geometry"], "fidelity": plan["fidelity"],
            "movements": [translate(k, g, style) for g in groups(plan["events"])]}

